import json

from .store import redis


def search_key(filters: dict) -> str:
    return "search:" + json.dumps(filters, sort_keys=True)


def cached_search(filters, run):
    key = search_key(filters)
    hit = redis.get(key)
    if hit is not None:
        return json.loads(hit)
    result = run(filters)
    redis.set(key, json.dumps(result), ex=600)
    return result


def invalidate(filters: dict) -> None:
    """Drop the cached result for these filters after a product changes."""
    redis.delete("search:" + json.dumps(filters))
